<section data-tab-panel="bank-tax" hidden><div class="vc-grid two"><form class="vc-card" data-frontend-form="bank" data-success="Bank form validated. Sensitive data is not stored in this frontend."><div class="vc-card-head"><h2>Bank account</h2><span class="vc-status success">Verified</span></div><div class="vc-card-body"><div class="vc-field"><label for="vc-account-input-1">Account holder</label><input name="vc-account-input-1" id="vc-account-input-1" class="vc-input" autocomplete="off" required maxlength="100" value="Rajasthan Heritage Crafts"></div><div class="vc-field mt-2"><label for="vc-account-input-2">Account number</label><input name="vc-account-input-2" id="vc-account-input-2" class="vc-input" inputmode="numeric" autocomplete="off" pattern="[0-9]{9,18}" required placeholder="Enter only when connected securely"></div><div class="vc-field mt-2"><label for="vc-account-input-3">IFSC</label><input name="vc-account-input-3" id="vc-account-input-3" class="vc-input" autocomplete="off" pattern="[A-Z]{4}0[A-Z0-9]{6}" required maxlength="11"></div><div class="vc-form-actions"><button class="vc-btn primary" type="submit">Validate bank details</button></div></div></form><form class="vc-card" data-frontend-form="tax" data-success="Tax form validated. Backend verification will be required."><div class="vc-card-head"><h2>Tax configuration</h2></div><div class="vc-card-body"><div class="vc-field"><label for="vc-account-select-4">GST registration status</label><select name="vc-account-select-4" id="vc-account-select-4" class="vc-select"><option>Registered</option><option>Composition</option><option>Not registered</option></select></div><div class="vc-field mt-2"><label for="vc-account-input-5">GSTIN</label><input name="vc-account-input-5" id="vc-account-input-5" class="vc-input" pattern="[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]" maxlength="15" required></div><div class="vc-field mt-2"><label for="vc-account-input-6">Invoice prefix</label><input name="vc-account-input-6" id="vc-account-input-6" class="vc-input" pattern="[A-Z0-9/-]{2,20}" maxlength="20" value="RHC/26-27/"></div><div class="vc-form-actions"><button class="vc-btn primary" type="submit">Validate tax details</button></div></div></form></div></section>
